import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"StepperPreview","description":"","frontmatter":{"sidebarPos":4,"sidebarTitle":"Stepper Preview"},"headers":[],"relativePath":"guide/components/stepper/stepper-preview.md","filePath":"guide/components/stepper/stepper-preview.md","lastUpdated":1777448653000}'),r={name:"guide/components/stepper/stepper-preview.md"},a=o('<h1 id="stepperpreview" tabindex="-1">StepperPreview <a class="header-anchor" href="#stepperpreview" aria-label="Permalink to &quot;StepperPreview&quot;">​</a></h1><p><code>StepperPreview</code> is the main-column content for the final step. It shows two areas:</p><ol><li><strong>Formatted preview cards</strong> — a responsive grid of <code>ue-configurable-card</code> tiles built from <code>previewNotations</code>.</li><li><strong>Final form selectable cards</strong> — fetched items from <code>finalFormFields</code> that the user can add or remove from the payload before submitting.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This is an internal sub-component of <code>ue-stepper-form</code>. You do not use it directly.</p></div><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li><code>formattedPreview</code> is passed in already-formatted from <code>StepperForm</code> via <code>NotationUtil.formattedPreview</code>.</li><li>Each card in <code>previewFormData</code> (fetched via <code>finalFormFields[n].endpoint</code>) renders a <code>ue-configurable-card</code> with a toggle button (<code>mdi-plus</code> / <code>mdi-minus</code>).</li><li>Clicking the toggle button emits <code>final-form-action</code> with <code>{ index, event }</code> where <code>event</code> is the new boolean selected state.</li><li>Items present in <code>protectedLastStepModel</code> are rendered as read-only (the toggle is disabled) — this is used when editing an existing record and some items were already committed.</li><li>Card appearance: selected items get <code>bg-primary</code>; unselected items get <code>bg-grey-lighten-5</code>.</li></ul><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>formattedPreview</code></td><td><code>Array</code></td><td>No</td><td><code>[]</code></td><td>Pre-formatted card data for the summary grid (top section). Each entry is a <code>ue-configurable-card</code> props object.</td></tr><tr><td><code>previewFormData</code></td><td><code>Array</code></td><td>No</td><td><code>[]</code></td><td>Fetched selectable items for the final form section (bottom section).</td></tr><tr><td><code>lastStepModel</code></td><td><code>Object</code></td><td>Yes</td><td>—</td><td>Object holding currently selected values, keyed by <code>fieldName</code>.</td></tr><tr><td><code>protectedLastStepModel</code></td><td><code>Object</code></td><td>No</td><td><code>{}</code></td><td>Initial model values that should be read-only.</td></tr><tr><td><code>finalFormTitle</code></td><td><code>String</code></td><td>Yes</td><td>—</td><td>Heading above the selectable cards.</td></tr><tr><td><code>finalFormSubtitle</code></td><td><code>String</code></td><td>No</td><td><code>null</code></td><td>Sub-heading below <code>finalFormTitle</code>.</td></tr></tbody></table><h2 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h2><table><thead><tr><th>Event</th><th>Payload</th><th>Description</th></tr></thead><tbody><tr><td><code>final-form-action</code></td><td><code>{ index: Number, event: Boolean }</code></td><td>Emitted when a card&#39;s toggle button is clicked. <code>index</code> is the item&#39;s position in <code>previewFormData</code>; <code>event</code> is <code>true</code> (add) or <code>false</code> (remove).</td></tr></tbody></table><h2 id="card-item-structure" tabindex="-1">Card Item Structure <a class="header-anchor" href="#card-item-structure" aria-label="Permalink to &quot;Card Item Structure&quot;">​</a></h2><p>Each entry in <code>previewFormData</code> is a fetched and transformed item. The relevant fields used by <code>StepperPreview</code>:</p><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>fieldName</code></td><td>Key in <code>lastStepModel</code> where the selection is stored</td></tr><tr><td><code>form_card_items</code></td><td>Array of values for each card column (name, description, tags, price, etc.)</td></tr><tr><td><code>_fieldFormat</code></td><td><code>&#39;id&#39;</code> or an object map — controls how selected values are stored</td></tr><tr><td><code>_fieldFormatSourceKey</code></td><td>Key on the item used as the source for uniqueness checks (default <code>&#39;id&#39;</code>)</td></tr><tr><td><code>_fieldFormatUniqueKey</code></td><td>Key used when matching against object-format stored values (default <code>&#39;id&#39;</code>)</td></tr></tbody></table><p>These fields are injected automatically by <code>StepperForm.handlePreviewFormField</code> based on the <code>finalFormFields</code> configuration.</p><h2 id="selection-logic" tabindex="-1">Selection Logic <a class="header-anchor" href="#selection-logic" aria-label="Permalink to &quot;Selection Logic&quot;">​</a></h2><table><thead><tr><th><code>_fieldFormat</code> value</th><th>Add behaviour</th><th>Remove behaviour</th></tr></thead><tbody><tr><td><code>String</code> (e.g. <code>&#39;id&#39;</code>)</td><td>Appends <code>item[fieldFormat]</code> to the array</td><td>Filters the value out of the array</td></tr><tr><td><code>Object</code> (field map)</td><td>Builds a new object from the map and appends it</td><td>Finds by <code>_fieldFormatUniqueKey</code> and splices it out</td></tr></tbody></table>',16),c=[a];function i(s,l,n,h,p,m){return d(),t("div",null,c)}const f=e(r,[["render",i]]);export{b as __pageData,f as default};
